fn test_line_retry_cannot_reinterpret_a_split_date_as_money() {
    let runs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let lines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let scr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rtp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let plan: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let joined: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let im: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cm: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(text, 49);
    crate::port::cells_push(text, 48);
    crate::port::cells_push(text, 47);
    crate::port::cells_push(text, 49);
    crate::port::cells_push(text, 53);
    crate::port::cells_push(text, 47);
    crate::port::cells_push(text, 48);
    crate::port::cells_push(text, 52);
    crate::port::cells_push(text, 49);
    crate::port::cells_push(text, 48);
    crate::port::cells_push(text, 49);
    crate::port::cells_push(text, 53);
    crate::port::cells_push(text, 46);
    crate::port::cells_push(text, 48);
    crate::port::cells_push(text, 52);
    sc_prep(scr);
    rt_prep(rtp);
    or_new(runs, 1, 0);
    or_set(runs, 0, orf_wfirst(), 0);
    or_set(runs, 0, orf_wcount(), 2);
    or_set(runs, 0, orf_lfirst(), 0);
    or_set(runs, 0, orf_lcount(), 1);
    or_new(runs, 1, 0);
    or_set(runs, 1, orf_pass(), op_line());
    or_set(runs, 1, orf_wfirst(), 2);
    or_set(runs, 1, orf_wcount(), 1);
    or_set(runs, 1, orf_lfirst(), 1);
    or_set(runs, 1, orf_lcount(), 1);
    ol_new(lines, 1, 100, 10, 165, 20, 100, 20, 165, 20, 0, 0, 0, 2);
    ol_new(lines, 1, 100, 10, 165, 20, 100, 20, 165, 20, 0, 0, 2, 1);
    ol_set(lines, 0, olf_run(), 0);
    ol_set(lines, 1, olf_run(), 1);
    ow_new(words, 1, 100, 10, 120, 20, 100, 20, 120, 20, 0, 0, 0, 3, 0, 200, -1);
    ow_new(words, 1, 125, 10, 165, 20, 125, 20, 165, 20, 0, 0, 3, 5, 0, 200, -1);
    ow_new(words, 1, 100, 10, 165, 20, 100, 20, 165, 20, 0, 1, 8, 7, 0, 999, -1);
    crate::port::cells_set(scr, sc_sel_base(), 0);
    crate::port::cells_set(rtp, rtp_nl(), 1);
    crate::port::cells_set(rtp, rtp_line0(), 0);
    crate::port::cells_set(rtp, rtp_line0() + 1, 1);
    crate::testport::assert_eq(oa_line_fuse(1, rtp, runs, lines, words, text, scr, 1, rows, plan, joined, im, cm), 1, "selection remains one line");
    crate::testport::assert_eq(or_count(runs), 2, "a valid joined date cannot become a money amount");
    crate::testport::assert_eq(ow_count(words), 3, "a large margin cannot delete date punctuation");
    crate::testport::assert_eq(crate::port::cells_len(rows), 0, "no arbitration admission");
    crate::testport::assert_eq(crate::port::cells_at(scr, sc_sel_base()), 0, "the incumbent line remains selected");
}
